import data.glitch_lib

suspicious_keywords := {"TODO", "FIXME", "BUG", "HACK", "WORKAROUND", "TEMPORARY", "INSECURE", "UNSAFE", "VULNERABLE"}
remediation_tags := {"RESOLVED", "VERIFIED", "SECURITY-REVIEWED", "SECURE"}
metadata_fields := {"description", "notes", "annotations", "comment", "remark", "metadata", "risk", "security-level", "compliance"}
security_sensitive_types := {"security-group", "firewall", "encryption", "access-control", "security", "firewall-rule", "network-acl", "security-policy"}
security_sensitive_attrs := {"publicly_accessible", "encryption_enabled", "allow_unauthenticated", "security_level", "risk"}

has_security_sensitive_units(unit_block) {
    some atomic_unit in unit_block.atomic_units
    some security_sensitive_type in security_sensitive_types
    contains(atomic_unit.type, security_sensitive_type)
} else {
    some atomic_unit in unit_block.atomic_units
    some attr in atomic_unit.attributes
    some security_sensitive_attr in security_sensitive_attrs
    attr.name == security_sensitive_attr
} else {
    some attr in unit_block.attributes
    some security_sensitive_attr in security_sensitive_attrs
    attr.name == security_sensitive_attr
}

contains_suspicious_without_remediation(str) {
    some keyword in suspicious_keywords
    contains(str, keyword)
    not some tag in remediation_tags
    contains(str, tag)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]
    contains_suspicious_without_remediation(comment.content)
    has_security_sensitive_units(parent)
    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious keyword in comment without remediation tag, associated with security-sensitive resource."
